function run(input, params, h) {
  const sizes = ["", "Change exactly one number.", "Change two or three numbers.", "Change a few numbers, or add or remove one simple command.", "Make a small change to the shape.", "Make a noticeable change, but keep the program recognizable.", "Change the structure in a meaningful way.", "Transform the main structure.", "Make it radically different.", "Reimagine it almost entirely.", "Use the program only as a starting point."];
  const program = input.data.winner || input.text;
  const size = sizes[Math.max(1, Math.min(10, Math.round(Number(params.size) || 5)))];
  const suggestion = input.data.suggestion ? "\nThe Critic suggests: " + input.data.suggestion : "";
  return { program: program, say: "Taste: " + params.taste + "\nHow big a change: " + size + "\nThe program to change:\n" + program + suggestion };
}

function run(input, params, h) {
  const messages = input.messages || [];
  const programs = messages.filter(m => typeof m.data.program === "string").map(m => ({ program: m.data.program, by: m.data.by || m.from }));
  const critic = messages.filter(m => Array.isArray(m.data.scores))[0] || { data: { scores: [], suggestion: "" } };
  const scored = programs.map((p, i) => ({ program: p.program, by: p.by, picture: i + 1, score: Number(critic.data.scores[i]) || 0 }));
  if (scored.length === 0) {
    return { say: "There were no pictures to choose from.", winner: "", suggestion: "" };
  }
  let winner = scored[0];
  if (params.choosing === "best") {
    for (const s of scored) {
      h.tick();
      if (s.score > winner.score) {
        winner = s;
      }
    }
  } else {
    const tickets = [];
    for (const s of scored) {
      for (let k = 0; k < Math.max(1, s.score); k++) {
        tickets.push(s);
      }
    }
    winner = h.pick(tickets);
  }
  return { winner: winner.program, picture: winner.picture, score: winner.score, scores: scored.map(s => s.score), suggestion: critic.data.suggestion || "", say: "Picture " + winner.picture + " (" + winner.by + "'s) wins with " + winner.score + " out of 10." + (critic.data.suggestion ? " The Critic suggests: " + critic.data.suggestion : "") };
}

function run(input, params, h) {
  const story = input.memory || [];
  if (h.count(input.text) === 0) {
    return { sentences: story.length, say: story.join(" "), memory: story };
  }
  const now = story.concat([input.text]);
  return { sentences: now.length, say: now.join(" "), memory: now };
}
